insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F1'), 3, '{"en": "Study the area and the pricing until I can answer any question about it", "ms-MY": "Kaji kawasan dan harga sehingga saya boleh jawab apa-apa soalan mengenainya", "id-ID": "Mempelajari area dan harga sampai saya bisa menjawab pertanyaan apa pun tentangnya"}'::jsonb, '{"style.detail": 2, "role.presenter": 0.8}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F1'), 4, '{"en": "Build an online presence so people start coming to me", "ms-MY": "Bina kehadiran dalam talian supaya orang mula datang kepada saya", "id-ID": "Membangun kehadiran online agar orang mulai datang kepada saya"}'::jsonb, '{"role.content_creator": 2, "style.visibility": 1}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='F'), 'F2', 'scenario', '{"en": "Someone you have shown several properties to suddenly stops replying. What do you do?", "ms-MY": "Seseorang yang anda telah tunjukkan beberapa hartanah tiba-tiba berhenti membalas. Apa tindakan anda?", "id-ID": "Seseorang yang sudah Anda tunjukkan beberapa properti tiba-tiba berhenti membalas. Apa yang Anda lakukan?"}'::jsonb, null, 'role', false, true, true, null, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F2'), 1, '{"en": "Keep in touch lightly and regularly, without pushing", "ms-MY": "Kekal berhubung secara ringan dan tetap, tanpa mendesak", "id-ID": "Tetap berhubungan secara ringan dan teratur, tanpa mendesak"}'::jsonb, '{"role.relationship_builder": 2, "ent.persistence": 1}'::jsonb, 0);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F2'), 2, '{"en": "Call once and ask directly what is holding them back", "ms-MY": "Telefon sekali dan tanya terus apa yang menghalang mereka", "id-ID": "Menelepon sekali dan bertanya langsung apa yang menahan mereka"}'::jsonb, '{"role.closer": 2, "style.decision_speed": 1}'::jsonb, 1);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F2'), 3, '{"en": "Send them something useful and let them come back on their own", "ms-MY": "Hantar sesuatu yang berguna dan biar mereka kembali sendiri", "id-ID": "Mengirimkan sesuatu yang berguna dan membiarkan mereka kembali sendiri"}'::jsonb, '{"role.content_creator": 1.5, "style.autonomy": 0.5}'::jsonb, 2);
