insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='F'), 'F3', 'scenario', '{"en": "You have three free hours on a weekday and nobody has told you what to do. How do you spend them?", "ms-MY": "Anda ada tiga jam lapang pada hari bekerja dan tiada siapa beritahu apa nak buat. Bagaimana anda gunakannya?", "id-ID": "Anda punya tiga jam kosong di hari kerja dan tidak ada yang menyuruh apa pun. Bagaimana Anda memakainya?"}'::jsonb, null, 'role', false, true, true, null, 2);
