insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='F'), 'F5', 'scenario', '{"en": "You are asked to present to twenty people you have never met, next week. How do you feel about it?", "ms-MY": "Anda diminta membentangkan kepada dua puluh orang yang anda tidak pernah temui, minggu depan. Bagaimana perasaan anda?", "id-ID": "Anda diminta presentasi di depan dua puluh orang yang belum pernah Anda temui, minggu depan. Bagaimana perasaan Anda?"}'::jsonb, null, 'role', false, true, true, null, 4);
