insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F5'), 3, '{"en": "I would rather talk to them one at a time", "ms-MY": "Saya lebih suka bercakap dengan mereka seorang demi seorang", "id-ID": "Saya lebih suka berbicara dengan mereka satu per satu"}'::jsonb, '{"role.relationship_builder": 2, "style.autonomy": 0.5}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F5'), 4, '{"en": "I would do it, but it would cost me a lot of energy", "ms-MY": "Saya akan lakukannya, tetapi ia memerlukan tenaga yang banyak", "id-ID": "Saya akan melakukannya, tetapi itu menguras banyak energi saya"}'::jsonb, '{"success.resilience": 1.5, "demotivator.public_pressure": 1}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='F'), 'F6', 'scenario', '{"en": "Someone newer than you asks you to teach them what you have learned. What happens?", "ms-MY": "Seseorang yang lebih baharu daripada anda minta anda mengajar apa yang anda telah pelajari. Apa yang berlaku?", "id-ID": "Seseorang yang lebih baru dari Anda meminta diajari apa yang sudah Anda pelajari. Apa yang terjadi?"}'::jsonb, null, 'role', false, true, true, null, 5);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F6'), 1, '{"en": "I sit with them and walk through it properly", "ms-MY": "Saya duduk bersama mereka dan terangkan dengan betul", "id-ID": "Saya duduk bersama mereka dan menjelaskannya dengan benar"}'::jsonb, '{"role.coach_trainer": 2, "motivation.helping_others": 1}'::jsonb, 0);
