insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F6'), 3, '{"en": "I share what I have and get back to my own targets", "ms-MY": "Saya kongsi apa yang ada dan kembali kepada sasaran saya sendiri", "id-ID": "Saya membagikan yang saya punya lalu kembali ke target saya sendiri"}'::jsonb, '{"success.goal_focus": 1.5, "style.autonomy": 1}'::jsonb, 2);
insert into talent_options (question_id, value, label, contributes, sort_order) values ((select q.id from talent_questions q join talent_sections s on s.id=q.section_id join talent_versions v on v.id=s.version_id where v.code='myself-v1' and q.code='F6'), 4, '{"en": "I would want more people like them around me", "ms-MY": "Saya mahu lebih ramai orang seperti mereka di sekeliling saya", "id-ID": "Saya ingin lebih banyak orang seperti mereka di sekitar saya"}'::jsonb, '{"role.recruiter": 2, "motivation.leadership_influence": 1}'::jsonb, 3);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='G'), 'G1', 'text', '{"en": "Why are you looking at real estate now, at this point in your life?", "ms-MY": "Mengapa anda melihat bidang hartanah sekarang, pada waktu ini dalam hidup anda?", "id-ID": "Mengapa Anda melirik properti sekarang, di titik ini dalam hidup Anda?"}'::jsonb, null, 'reflection', false, false, false, 1500, 0);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='G'), 'G2', 'text', '{"en": "What are you willing to do consistently for the next 12 months to make it work?", "ms-MY": "Apakah yang anda sanggup lakukan secara konsisten dalam 12 bulan akan datang untuk menjayakannya?", "id-ID": "Apa yang bersedia Anda lakukan secara konsisten dalam 12 bulan ke depan agar berhasil?"}'::jsonb, null, 'reflection', false, false, false, 1500, 1);
insert into talent_questions (section_id, code, kind, stem, helper, dimension, reverse_scored, randomise_options, required, max_length, sort_order) values ((select s.id from talent_sections s join talent_versions v on v.id=s.version_id where v.code='myself-v1' and s.code='G'), 'G3', 'text', '{"en": "What usually causes you to stop, delay, or lose confidence?", "ms-MY": "Apakah yang biasanya menyebabkan anda berhenti, bertangguh atau hilang keyakinan?", "id-ID": "Apa yang biasanya membuat Anda berhenti, menunda, atau kehilangan kepercayaan diri?"}'::jsonb, null, 'reflection', false, false, false, 1500, 2);
